import pandas as pd
import numpy as np

# Load all available experiments
experiments = {}
for i in [1, 2, 3, 5, 6, 7, 8]:
    try:
        df = pd.read_csv(f'experiment_{i}_csv')
        experiments[f'e{i}'] = df
        print(f"=== e{i} columns: {list(df.columns)} ===")
        print(f"  JobThroughput mean: {df['JobThroughput'].mean():.3f}")
        if 'CoolingAggressiveness' in df.columns:
            print(f"  CoolingAggressiveness mean: {df['CoolingAggressiveness'].mean():.3f}")
        if 'PduLoad' in df.columns:
            print(f"  PduLoad mean: {df['PduLoad'].mean():.3f}")
        print()
    except Exception as e:
        print(f"Could not load e{i}: {e}")

# Look for any network-related columns across all experiments
all_cols = set()
for name, df in experiments.items():
    all_cols.update(df.columns)
print(f"\nAll columns seen: {sorted(all_cols)}")

# Check for network metrics
net_keywords = ['network', 'ethernet', 'link', 'crc', 'retrans', 'packet', 'nic', 'linecard', 'inlet', 'temp']
for col in sorted(all_cols):
    if any(kw in col.lower() for kw in net_keywords):
        print(f"\nNetwork-related column found: {col}")
        for name, df in experiments.items():
            if col in df.columns:
                print(f"  e{name}: mean={df[col].mean():.3f}, std={df[col].std():.3f}")
